&lt;/head&gt;
&lt;body class=&quot;spark-widget-shell&quot;&gt;
&lt;script&gt;
const { state } = WH.createApp({
    title: &quot;Joystick Sensor Comparison&quot;,
    params: {
        x: { value: 0, min: -100, max: 100, step: 1, label: &quot;Joystick X&quot; },
        y: { value: 0, min: -100, max: 100, step: 1, label: &quot;Joystick Y&quot; },
        sensorType: { 
            type: &#39;segmented&#39;, 
            value: &quot;2-Axis Orthogonal&quot;, 
            options: [&quot;2-Axis Orthogonal&quot;, &quot;3-Point Trilateration&quot;], 
            label: &quot;Sensor Type&quot; 
        }
    },
    internal_state: {
        magnetPos: { x: 0, y: 0 },
        sensorReadings: [0, 0, 0]
    },
    sizing: { viz: { height: 420 } },
    editorial: {
        hud: [
            { label: &quot;Position&quot;, value: &quot;0, 0&quot; },
            { label: &quot;Measurement&quot;, value: &quot;0.00&quot; }
        ]
    }
});

WH.initCanvas(&#39;viz&#39;, ({ ctx, width, height, cx, cy, minDim, state }) =&gt; {

    // UI Update logic
    const updateHUD = () =&gt; {
        const xStr = state.x.toFixed(0);
        const yStr = state.y.toFixed(0);
        let measureStr = &quot;&quot;;

        if (state.sensorType === &quot;2-Axis Orthogonal&quot;) {
            const sx = Math.max(0, 100 - Math.abs(state.x));
            const sy = Math.max(0, 100 - Math.abs(state.y));
            measureStr = `X:${sx.toFixed(0)} Y:${sy.toFixed(0)}`;
        } else {
            const dist = Math.sqrt(state.x * state.x + state.y * state.y);
            measureStr = `R:${dist.toFixed(1)}`;
        }

        ui.setEditorial({
            hud: [
                { label: &quot;Position&quot;, value: `${xStr}, ${yStr}` },
                { label: &quot;Readout&quot;, value: measureStr }
            ]
        });
    };

    state._subscribe(&#39;x&#39;, updateHUD);
    state._subscribe(&#39;y&#39;, updateHUD);
    state._subscribe(&#39;sensorType&#39;, updateHUD);
    updateHUD();

    // Visual Constants
    const SCALE = minDim * 0.4 / 100; // 100 units = 40% of min dimension
    const SENSOR_RADIUS = 8;
    const MAGNET_RADIUS = 12;

    return ({ ctx, width, height, cx, cy, minDim, time, pointer, frameCount }) =&gt; {
        // Handle pointer interaction (Draggable Magnet)
        if (pointer.isDown) {
            const nx = (pointer.x - cx) / SCALE;
            const ny = (pointer.y - cy) / SCALE;
            state.x = WH.clamp(nx, -100, 100);
            state.y = WH.clamp(ny, -100, 100);
        }

        const mx = cx + state.x * SCALE;
        const my = cy + state.y * SCALE;

        // Draw Background Grid
        ctx.strokeStyle = WH.getColor(&#39;--outline-variant&#39;);
        ctx.setLineDash([5, 5]);
        ctx.beginPath();
        ctx.moveTo(cx - 100 * SCALE, cy);
        ctx.lineTo(cx + 100 * SCALE, cy);
        ctx.moveTo(cx, cy - 100 * SCALE);
        ctx.lineTo(cx, cy + 100 * SCALE);
        ctx.stroke();
        ctx.setLineDash([]);

        // Rendering Logic based on Sensor Type
        if (state.sensorType === &quot;2-Axis Orthogonal&quot;) {
            const sensorX = { x: cx + 110 * SCALE, y: cy, label: &#39;HX&#39; };
            const sensorY = { x: cx, y: cy + 110 * SCALE, label: &#39;HY&#39; };

            // Projection Lines
            ctx.strokeStyle = WH.transparent(&#39;--on-surface-de-emphasis&#39;, 0.3);
            ctx.beginPath();
            ctx.moveTo(mx, my); ctx.lineTo(mx, cy);
            ctx.moveTo(mx, my); ctx.lineTo(cx, my);
            ctx.stroke();

            // Sensors
            [sensorX, sensorY].forEach((s, i) =&gt; {
                ctx.fillStyle = WH.getColor(`--chart-${i + 1}`);
                ctx.beginPath();
                ctx.arc(s.x, s.y, SENSOR_RADIUS, 0, Math.PI * 2);
                ctx.fill();
                ctx.drawTag(s.label, s.x, s.y - 12, { colorToken: `--chart-${i + 1}` });
            });

            // Field Strength Vectors (Relative to distance from axes)
            const magX = WH.clamp(100 - Math.abs(state.x), 5, 100) * 0.4 * SCALE;
            const magY = WH.clamp(100 - Math.abs(state.y), 5, 100) * 0.4 * SCALE;

            ctx.drawArrow(sensorX.x, sensorX.y, -magX, 0, &#39;--chart-1&#39;);
            ctx.drawArrow(sensorY.x, sensorY.y, 0, -magY, &#39;--chart-2&#39;);

        } else {
            // 3-Point Trilateration
            const sensors = [];
            for (let i = 0; i &lt; 3; i++) {
                const angle = (i * 120 - 90) * (Math.PI / 180);
                const r = 110 * SCALE;
                sensors.push({
                    x: cx + Math.cos(angle) * r,
                    y: cy + Math.sin(angle) * r,
                    label: `S${i + 1}`,
                    color: `--chart-${i + 1}`
                });
            }

            sensors.forEach(s =&gt; {
                const dx = mx - s.x;
                const dy = my - s.y;
                const dist = Math.sqrt(dx * dx + dy * dy);

                // Trilateration Circle
                ctx.strokeStyle = WH.transparent(s.color, 0.4);
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.arc(s.x, s.y, dist, 0, Math.PI * 2);
                ctx.stroke();

                // Sensor Body
                ctx.fillStyle = WH.getColor(s.color);
                ctx.beginPath();
                ctx.arc(s.x, s.y, SENSOR_RADIUS, 0, Math.PI * 2);
                ctx.fill();

                // Vector towards magnet
                const arrowLen = Math.min(dist * 0.3, 40);
                ctx.drawArrow(s.x, s.y, (dx / dist) * arrowLen, (dy / dist) * arrowLen, s.color);
            });
        }

        // Draw Magnet (the Joystick knob)
        const pulse = Math.sin(time * 4) * 2;
        ctx.fillStyle = WH.getColor(&#39;--primary&#39;);
        ctx.shadowBlur = 15;
        ctx.shadowColor = WH.transparent(&#39;--primary&#39;, 0.5);
        ctx.beginPath();
        ctx.arc(mx, my, MAGNET_RADIUS + pulse, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Label Magnet
        ctx.fillStyle = WH.getColor(&#39;--on-primary&#39;);
        ctx.font = &#39;10px sans-serif&#39;;
        ctx.textAlign = &#39;center&#39;;
        ctx.textBaseline = &#39;middle&#39;;
        ctx.fillText(&#39;N/S&#39;, mx, my);

        // Limit Area Boundary
        ctx.strokeStyle = WH.getColor(&#39;--outline&#39;);
        ctx.lineWidth = 1;
        ctx.strokeRect(cx - 100 * SCALE, cy - 100 * SCALE, 200 * SCALE, 200 * SCALE);
    };
}, { height: 420 });
